 * @description ipt_prtdepoShrs 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_prtdepoShrs_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07380.ipt_prtdepoShrs_onclick' }); }
};

/**
 * @method
 * @name ipt_prtdepoShrs_onkeyup
